def _stats():
    users=User.query.filter_by(is_banned=False).count()
    emails=EmailSubmission.query.count()
    accepted=EmailSubmission.query.filter_by(status='accepted').count()
    paid=db.session.query(db.func.coalesce(db.func.sum(EmailSubmission.payout),0)).filter(EmailSubmission.status=='accepted').scalar() or 0
    return users,emails,accepted,Decimal(paid)

def _home_visual():
    if current_user(): return redirect(url_for('dashboard'))
    users,emails,accepted,paid=_stats()
    success=(accepted/emails*100) if emails else 0
    body=f'''<div class="mm-home"><section class="mm-hero"><div class="mm-hero-inner"><div><div class="mm-kicker">◉ Platform Setoran Email Terpercaya</div><h1>Jadikan Emailmu<br><span>Lebih Bernilai</span></h1><p>Ajukan emailmu dengan mudah. Semua pengajuan diperiksa secara manual agar proses tetap transparan dan rapi.</p><div class="mm-actions"><a class="btn" href="/register">Mulai Sekarang →</a><a class="btn secondary" href="#cara-kerja">Cara Kerja</a></div><div class="mm-proof"><span>✓ Verifikasi Manual</span><span>✓ Pembayaran Transparan</span><span>✓ Proses Terpantau</span></div></div><div class="mm-preview"><div class="mm-preview-top"><span>Ringkasan Aktivitas</span><b>Live</b></div><div class="mm-balance"><small>Total dibayarkan</small><strong>Rp {paid:,.0f}</strong><small>Berdasarkan email yang telah disetujui</small></div><div class="mm-mini-row"><div class="mm-mini"><small>Pengguna</small><strong>{users:,}+</strong></div><div class="mm-mini"><small>Email diproses</small><strong>{emails:,}+</strong></div></div></div></div></section><div class="mm-stats"><div class="mm-stat"><small>Pengguna Aktif</small><strong>{users:,}+</strong></div><div class="mm-stat"><small>Email Diproses</small><strong>{emails:,}+</strong></div><div class="mm-stat"><small>Tingkat Disetujui</small><strong>{success:.1f}%</strong></div><div class="mm-stat"><small>Total Dibayarkan</small><strong>Rp {paid:,.0f}</strong></div></div><section class="mm-main" id="fitur"><div class="section-title"><div class="muted small">FITUR UTAMA</div><h2>Semua yang kamu butuhkan dalam satu tempat</h2><p>Yang ditampilkan di sini adalah fitur yang memang sudah tersedia di website kamu — tidak dibuat ganda.</p></div><div class="mm-features"><div class="mm-feature"><div class="mm-icon">♢</div><h3>Verifikasi Manual</h3><p>Setiap email diperiksa admin sebelum saldo bertambah.</p><a href="/rules">Selengkapnya →</a></div><div class="mm-feature"><div class="mm-icon">▤</div><h3>Riwayat Setoran</h3><p>Pantau status pending, diterima, dan ditolak dari dashboard.</p><a href="/dashboard">Lihat Riwayat →</a></div><div class="mm-feature"><div class="mm-icon">↥</div><h3>Input Massal</h3><p>Masukkan banyak email sekaligus melalui halaman pengajuan.</p><a href="/submit">Mulai Ajukan →</a></div><div class="mm-feature"><div class="mm-icon">▣</div><h3>Pencairan Dana</h3><p>Ajukan withdraw dan pantau proses persetujuan admin.</p><a href="/withdraw">Tarik Dana →</a></div></div><div class="section-title" id="cara-kerja" style="margin-top:48px"><div class="muted small">CARA KERJA</div><h2>Proses sederhana, status tetap jelas</h2></div><div class="mm-how"><div class="mm-step"><div class="mm-step-num">1</div><div><h3>Kirim Email</h3><p>Masukkan email secara manual atau massal melalui halaman pengajuan.</p></div></div><div class="mm-step"><div class="mm-step-num">2</div><div><h3>Verifikasi Manual</h3><p>Admin memeriksa setiap pengajuan dan menentukan diterima atau ditolak.</p></div></div><div class="mm-step"><div class="mm-step-num">3</div><div><h3>Terima Imbalan</h3><p>Email yang diterima menambah saldo sesuai harga saat pengajuan.</p></div></div></div><div class="mm-trust" id="bantuan"><div class="mm-trust-items"><div class="mm-trust-item"><b>🔒 Data Privat</b><span>Data pengajuan tersimpan di sistem.</span></div><div class="mm-trust-item"><b>✓ Review Manual</b><span>Tidak ada penerimaan otomatis.</span></div><div class="mm-trust-item"><b>💳 Pencairan</b><span>DANA · GoPay · OVO / tujuan yang didukung.</span></div></div></div><div class="mm-cta"><div><h2>Siap mulai?</h2><p>Buat akun gratis dan lihat aturan sebelum mengajukan.</p></div><a class="btn secondary" href="/register">Daftar Gratis →</a></div></section><footer class="mm-footer"><div><div class="brand"><i class="brand-mark"></i>Mail<span>Market</span></div><p>Platform setoran email dengan proses review manual dan pencatatan saldo transparan.</p></div><div><h4>Menu</h4><a href="/">Beranda</a><a href="#cara-kerja">Cara Kerja</a><a href="/rules">Aturan</a></div><div><h4>Akun</h4><a href="/login">Masuk</a><a href="/register">Daftar Gratis</a></div><div><h4>Bantuan</h4><a href="/rules">Syarat Pengajuan</a><a href="/login">Bantuan Admin</a></div><div class="mm-copy">© 2026 MailMarket. Semua hak dilindungi.</div></footer></div>'''
    return page(body,'Beranda')

